"""results/temporal/stage3/REPORT.md: stage-3 DiT arms and read 3 (DiT half), generated from the JSONs."""
import json, os, sys
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from boa_dit.common import atomic_write_text
from boa_dit.temporal.common import OUT, boot_reduction
from boa_dit.temporal.decide import spent

E = lambda n: json.load(open(os.path.join(OUT, "eval", f"dit_bp_{n}.json"))) if os.path.exists(os.path.join(OUT, "eval", f"dit_bp_{n}.json")) else None
pct = lambda r: f"{-100 * r['reduction']:+.1f}% [{-100 * r['ci'][1]:+.1f}, {-100 * r['ci'][0]:+.1f}]"
arms = [("single8_none", "1. single table (baseline)"), ("single8_sym2", "2. ±Δ/4 symmetric period-2"),
        ("single8_unif", "3. independent uniform subtractive dither"), ("single8_cyc4a", "4a. 4-phase cycling (0,1,2,3)"),
        ("single8_cyc4b", "4b. 4-phase cycling (0,2,1,3)"), ("single8_feedback", "5. full temporal error feedback (guarded)"),
        ("step8_none", "6. per-step scale tables (reference)")]
b = E("single8_none")
L = ["# Stage 3, DiT-XL/2 (W16A8 static, single table, smoothed fc1/fc2): report (generated by `scripts/make_stage3.py`)", "",
     f"Eval seeds 0–511; paired 95% bootstrap CIs; change is negative = lower latent MSE. Compute logged for stage `temporal`: {spent():.2f} A30-h "
     "(stage 1–4 ceiling 7.99 h).", "",
     "| arm | latent rel. MSE | vs arm 1 [95% CI] | vs arm 5 [95% CI] | prediction C/I | step-mean energy fraction | clip rate (x) |",
     "| --- | ---: | --- | --- | ---: | ---: | ---: |"]
f = E("single8_feedback")
for n, lab in arms:
    a = E(n)
    if a is None:
        L.append(f"| {lab} | not run (budget ceiling) | | | | | |"); continue
    v1 = "—" if n == "single8_none" else pct(boot_reduction(a["rel_mse_per_image"], b["rel_mse_per_image"]))
    v5 = "—" if n == "single8_feedback" or f is None else pct(boot_reduction(f["rel_mse_per_image"], a["rel_mse_per_image"])).replace("+", "±", 0)
    import numpy as np
    L.append(f"| {lab} | {a['rel_mse_mean']:.5f} ± {a['rel_mse_sem']:.5f} | {v1} | {v5} | {a['diag']['C_over_I']:.4f} | {a['diag']['C_share']:.4f} | {np.mean(a['clip_rate_per_step']):.4%} |")
L += ["", "Column 'vs arm 5' = feedback's change relative to that arm (negative = feedback lower).", ""]
r15 = boot_reduction(f["rel_mse_per_image"], b["rel_mse_per_image"])
stat = [n for n in ("single8_sym2", "single8_unif", "single8_cyc4a", "single8_cyc4b") if E(n)]
over = {n: boot_reduction(f["rel_mse_per_image"], E(n)["rel_mse_per_image"]) for n in stat}
clears = {n: boot_reduction(E(n)["rel_mse_per_image"], b["rel_mse_per_image"]) for n in stat}
best = max(stat, key=lambda n: clears[n]["reduction"])
L += ["## Read 3, DiT half (the registered read needs both beds and ≥ 0.3 dB on PixArt; PixArt not run)", "",
      f"- Feedback vs single table: {pct(r15)}. Needs ≥ 10% with CI > 0 → **{'met' if r15['reduction'] >= 0.10 and r15['ci'][0] > 0 else 'not met'}** on DiT.",
      "- Feedback vs each stateless arm run: " + "; ".join(f"{n.split('_')[1]} {pct(over[n])}" for n in stat) + " → "
      + ("**beats every stateless arm run**" if all(over[n]["reduction"] > 0 and over[n]["ci"][0] > 0 for n in stat) else "does not beat every stateless arm") + ".",
      f"- Stateless arms that clear the ≥ 10% bar on DiT: " + ", ".join(f"{n.split('_')[1]} {pct(clears[n])}" for n in stat if clears[n]['reduction'] >= 0.10 and clears[n]['ci'][0] > 0)
      + f". Best stateless arm: **{best.split('_')[1]}**. Feedback adds {pct(over[best])} over it. The 'stateless is the construction' clause needs feedback to add < 5%: "
      + ("point estimate ≥ 5% → that clause **does not hold**" if over[best]["reduction"] >= 0.05 else "point estimate < 5% → that clause **holds**")
      + (" (the CI's lower bound is below 5%, so this is narrow)." if over[best]["ci"][0] < 0.05 <= over[best]["reduction"] else "."),
      "- Arm 4 (4-phase cycling, both orders) was **not run** (budget ceiling), so 'beats arms 2–4' is evaluated on arms 2–3 only.",
      "- **Outcome label for feedback:** cancellation **constructed and survived downstream**. The rounding part is bounded at the "
      "sites (identity closes to ≤ 1e-7; ‖s_last‖ ≤ Δ/2, ‖Ση‖ ≈ 0.02, ‖Σd‖ ≤ 0.09 on the checked layers). Prediction C/I falls "
      f"0.133 → {f['diag']['C_over_I']:.3f}, and the endpoint falls {pct(r15)}. The cumulative site error that remains is the "
      "baseline's own input-clip error Σc (identical in both arms, step-constant, never fed back by design). None of the three "
      "failure labels (not constructed / lost to representation / lost downstream) applies.",
      "- The per-step reference is *worse* than the single table on this bed (prediction C/I doubles). B′'s '≥ 50% of the "
      "per-step gain' criterion has no gain to recover: reported, not applied.", ""]
# ---------------------------------------------------------------- feedback cost: simulation vs deployed
def state_bytes(sites, tokens, rows=2):
    """one fp16 residual per quantizer site, per CFG row: sum over sites of rows x tokens x c_in x 2 bytes."""
    return sum(rows * tokens * c * 2 for c in sites)
dit_sites = [1152, 1152, 1152, 4608] * 28                                  # qkv, proj, fc1, fc2 inputs, 28 blocks
pix_sites = [1152] * 3 + [1152, 1152, 1152, 1152, 4608]                     # attn1 q/k/v, attn1 out, attn2 q, attn2 out, fc1, fc2
pix_shared = [1152, 1152, 1152, 1152, 1152, 4608]                          # attn1 q/k/v share one input -> one residual
L += ["## Feedback cost: simulation vs deployment", "",
      f"- **Instrumented implementation:** the feedback arm cost {E('single8_feedback')['gpu_hours']:.2f} A30-h for 512 seeds, against "
      f"{E('single8_none')['gpu_hours']:.2f} h for the single table. The instrumented implementation is approximately "
      f"{E('single8_feedback')['gpu_hours'] / E('single8_none')['gpu_hours']:.0f}× slower. It uses per-site Python state and "
      "diagnostic operations; runtime without diagnostics remains to be measured. One batch of 32 with the counters off took "
      "73.7 s vs 37.0 s for the baseline, and 16.3 s for unquantized sampling (a single timing, not a benchmark).",
      "- **Deployed cost (full feedback):** one fp16 residual tensor per quantizer site, held across steps. Per site and step: "
      "one add before the rounding (u = x + s), one subtract after it (r = ũ − q̂), the guard's clamp and the clip, the "
      "residual's read and write, and the precision conversion of the stored state. There is no extra matmul. Memory "
      "traffic from the residual reads and writes may remain significant even without Python overhead. Compressed "
      "feedback (stage 4) adds projection and reconstruction costs.", "",
      "| model (resolution, tokens) | quantizer sites | residual state per image (2 CFG rows, fp16) | per CFG row |", "| --- | ---: | ---: | ---: |",
      f"| DiT-XL/2 (256², 256 tokens) | {len(dit_sites)} | {state_bytes(dit_sites, 256) / 2**20:.0f} MiB | {state_bytes(dit_sites, 256, 1) / 2**20:.0f} MiB |",
      f"| PixArt-Σ (1024², 4,096 tokens), sites as quantized here | {28 * len(pix_sites)} | {state_bytes(pix_sites * 28, 4096) / 2**30:.2f} GiB | {state_bytes(pix_sites * 28, 4096, 1) / 2**30:.2f} GiB |",
      f"| PixArt-Σ, attn1 q/k/v sharing one input residual | {28 * len(pix_shared)} | {state_bytes(pix_shared * 28, 4096) / 2**30:.2f} GiB | {state_bytes(pix_shared * 28, 4096, 1) / 2**30:.2f} GiB |",
      "", "Memory is the real deployment cost: the state scales with tokens × channels summed over every quantized input. On "
      "PixArt-Σ at 1024² it is several GiB per image, which is why stage 4's compressed (k-dimensional spatial) state exists.", ""]
atomic_write_text(os.path.join(OUT, "stage3", "REPORT.md"), "\n".join(L) + "\n")
print("\n".join(L))
